--
-- PRODUCT NAMES ARE DATA (Arman, 2026-10-20: "search finds a connector by the products it covers").
-- Each connector row carries `products`: a list of {name, aliases[]} a person might type to find it
-- (Outlook and Teams for Microsoft, Jira for Atlassian). The chat's Connections menu and the
-- Browse-all-connectors window both search it; no UI code keeps a list of its own.
-- `public.get_mcp_catalog_for_user` returns it with the rest of the catalog row (changed in the
-- database directly, because its return type grew by one column).

alter table tool.mcp_server add column if not exists products jsonb not null default '[]'::jsonb;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'mcp_server_products_is_array') then
    alter table tool.mcp_server add constraint mcp_server_products_is_array check (jsonb_typeof(products) = 'array');
  end if;
end $$;

comment on column tool.mcp_server.products is 'What a person would search for to find this connector: a list of {name, aliases[]} (e.g. Outlook, Teams for Microsoft). Read by the chat connections menu and the connectors directory search.';

